cycle.pseudocode:
def has_cycle(graph):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {v: WHITE for v in graph}

    def dfs(u):
        color[u] = GRAY  # 방문 중
        for v in graph[u]:
            if color[v] == GRAY:  # 역방향 간선 = 순환
                return True
            if color[v] == WHITE and dfs(v):
                return True
        color[u] = BLACK  # 방문 완료
        return False

    return any(color[v] == WHITE and dfs(v)
               for v in graph)

cyclic-group.pseudocode:
def prime_factors(n):
    f, d = set(), 2
    while d * d <= n:
        while n % d == 0:
            f.add(d)
            n //= d
        d += 1
    if n > 1:
        f.add(n)
    return f

def is_generator(g, p):  # Z_p* (차수 p-1)의 생성원 판정
    order = p - 1
    for q in prime_factors(order):
        if pow(g, order // q, p) == 1:  # 진부분군에 갇힘
            return False
    return True  # g^k가 Z_p*의 모든 원소를 생성

cyclic-redundancy-check.pseudocode:
def mod2_div(bits, gen):  # 비트 문자열, 나머지 반환
    buf = list(bits)
    r = len(gen) - 1
    for i in range(len(bits) - r):
        if buf[i] == '1':  # 선두가 1일 때만 XOR
            for j in range(len(gen)):
                same = buf[i + j] == gen[j]
                buf[i + j] = '0' if same else '1'
    return ''.join(buf[-r:])

def crc_encode(data, gen):
    r = len(gen) - 1
    return data + mod2_div(data + '0' * r, gen)  # + CRC

def crc_check(codeword, gen):
    return '1' not in mod2_div(codeword, gen)  # 나머지 0

