cylinder-head-sector.pseudocode:
def chs_to_lba(c, h, s, heads, spt):
    # spt: 트랙당 섹터 수, 섹터 번호는 1부터
    return (c * heads + h) * spt + (s - 1)

def lba_to_chs(lba, heads, spt):
    c = lba // (heads * spt)  # 실린더
    h = (lba // spt) % heads  # 헤드
    s = lba % spt + 1  # 섹터 (1부터)
    return c, h, s
